dtsPropsFor.Button:
/** Visual treatment. */
  variant?: 'default' | 'destructive' | 'outline' | 'secondary' | 'ghost' | 'link';
  /** Control height and padding. */
  size?: 'default' | 'sm' | 'lg' | 'icon';
  /** Render the child element instead of a <button>, keeping the styles. */
  asChild?: boolean;
  className?: string;
  disabled?: boolean;
  type?: 'button' | 'submit' | 'reset';
  onClick?: React.MouseEventHandler<HTMLButtonElement>;
  children?: React.ReactNode;
  /** Plus any native <button> attribute. */
  [key: string]: unknown;

dtsPropsFor.Input:
type?: React.HTMLInputTypeAttribute;
  value?: string | number;
  defaultValue?: string | number;
  placeholder?: string;
  disabled?: boolean;
  required?: boolean;
  autoComplete?: string;
  onChange?: React.ChangeEventHandler<HTMLInputElement>;
  className?: string;
  /** Plus any native <input> attribute. */
  [key: string]: unknown;

dtsPropsFor.Textarea:
value?: string;
  defaultValue?: string;
  placeholder?: string;
  rows?: number;
  disabled?: boolean;
  required?: boolean;
  onChange?: React.ChangeEventHandler<HTMLTextAreaElement>;
  className?: string;
  /** Plus any native <textarea> attribute. */
  [key: string]: unknown;

dtsPropsFor.Dialog:
/** Controlled open state. Pair with onOpenChange. */
  open?: boolean;
  defaultOpen?: boolean;
  onOpenChange?: (open: boolean) => void;
  /** Blocks interaction with the rest of the page while open. Default true. */
  modal?: boolean;
  /** Compose from DialogTrigger / DialogContent / DialogHeader /
   *  DialogTitle / DialogDescription / DialogFooter / DialogClose. */
  children?: React.ReactNode;

dtsPropsFor.Carousel:
/** Embla options, e.g. { align: 'start', loop: true }. */
  opts?: { align?: 'start' | 'center' | 'end'; loop?: boolean; [key: string]: unknown };
  /** Embla plugins. */
  plugins?: unknown[];
  orientation?: 'horizontal' | 'vertical';
  /** Receives the Embla API for external control. */
  setApi?: (api: unknown) => void;
  className?: string;
  /** Compose from CarouselContent / CarouselItem /
   *  CarouselPrevious / CarouselNext. */
  children?: React.ReactNode;

dtsPropsFor.Wordmark:
/** Wraps the mark in an <h1> on the page that owns the primary heading.
   *  Defaults to 'div'. */
  as?: 'h1' | 'div';
  /** Size it by overriding the width token, e.g.
   *  "[--wordmark-width:clamp(11rem,32vw,20rem)]". */
  className?: string;

dtsPropsFor.SocialLinks:
/** Positioning only — the link set comes from the design system's own
   *  config, not from props. */
  className?: string;
